script:
if not doc.is_new():
    previous = frappe.get_doc("Zapp Bouw7 Koppeling", doc.name)
    for field in ["state_json", "watermarks_json", "sync_status", "last_success", "last_completed", "last_heartbeat", "last_error"]:
        doc.set(field, previous.get(field))
if doc.application_id != "z-next":
    frappe.throw("De goedgekeurde applicatie-ID is z-next.")
if doc.batch_size < 10 or doc.batch_size > 250:
    frappe.throw("Gebruik 10 tot 250 records per achtergrondtaak.")

# Server Script API: zapp_bouw7_sync. No imports: RestrictedPython.
CONFIG_TYPE = "Zapp Bouw7 Koppeling"
CONFIG_NAME = "Bouw7"
LOG_TYPE = "Zapp Bouw7 Log"
ISSUE_TYPE = "Zapp Bouw7 Controle"
SCRIPT_METHOD = "zapp_bouw7_sync"
SOURCE_URL = "https://heimdall.bouw7.nl"
KINDS = ["contacts", "employees", "projects", "purchase_invoices", "sales_invoices"]
PATHS = {"contacts": "/list/contacts", "employees": "/list/employees", "projects": "/list/projects", "purchase_invoices": "/list/purchase-invoices", "sales_invoices": "/list/invoices"}

def text(value):
    return frappe.utils.cstr("" if value is None else value).strip()

def day(value):
    return text(value)[:10] or None

def cents(value):
    return round(frappe.utils.flt(value) * 100)

def source_key(row):
    return text(config.organisatie_id) + ":" + text(row.get("id"))

def candidates(dt, filters):
    return frappe.get_all(dt, filters=filters, fields=["name"], limit_page_length=3)

def mapped(dt, row):
    matches = candidates(dt, {"custom_bouw7_key": source_key(row)})
    return matches[0].name if len(matches) == 1 else None

def issue(kind, row, reason, target=None):
    identity = kind + ":" + text(row.get("id"))
    existing = frappe.db.exists(ISSUE_TYPE, identity)
    values = {"dataset": kind, "source_id": text(row.get("id")), "reason": reason[:1000], "target_doctype": target.doctype if target else None, "target_name": target.name if target else None, "last_seen": frappe.utils.now(), "resolved": 0}
    if existing:
        frappe.db.set_value(ISSUE_TYPE, existing, values, update_modified=False)
    else:
        values.update({"doctype": ISSUE_TYPE, "name": identity})
        frappe.get_doc(values).insert(ignore_permissions=True)
    return "conflict"

def resolve_issue(kind, row):
    identity = kind + ":" + text(row.get("id"))
    if frappe.db.exists(ISSUE_TYPE, identity):
        frappe.db.set_value(ISSUE_TYPE, identity, "resolved", 1, update_modified=False)

def company_for(row):
    branch = text((row.get("branch") or {}).get("name"))
    company = {text(config.bedrijf1_filiaal): config.bedrijf1_company, text(config.bedrijf2_filiaal): config.bedrijf2_company}.get(branch)
    division = frappe.utils.cint((row.get("division") or {}).get("id"))
    division_company = {frappe.utils.cint(config.bedrijf1_afdeling_id): config.bedrijf1_company, frappe.utils.cint(config.bedrijf2_afdeling_id): config.bedrijf2_company}.get(division)
    if company and division_company and company != division_company:
        frappe.throw("Filiaal en boekhoudadministratie spreken elkaar tegen; handmatige controle nodig.")
    if not branch and division_company:
        company = division_company
    if not company and not branch and row.get("entryNumber"):
        legacy = legacy_invoices.get("by_entry", {}).get(text(row["entryNumber"])) or {}
        if legacy.get("bill_no") == text(row.get("invoiceNumber")) and cents(legacy.get("net")) == cents(row.get("subTotal")) and cents(legacy.get("total")) == cents(row.get("total")):
            company = legacy.get("company")
    if not company:
        frappe.throw("Onbekend filiaal: " + (branch or "niet ingevuld") + ". Administratie niet geraden.")
    return company

def bind_doc(doc, row):
    key = doc.get("custom_bouw7_key")
    if key and key != source_key(row):
        frappe.throw("Doeldocument is al aan een andere Bouw7-ID gekoppeld.")
    doc.custom_bouw7_key = source_key(row)
    doc.custom_bouw7_updated = text(row.get("updatedAt"))

def save_doc(doc, row, values, existing):
    before = {k: doc.get(k) for k in values}
    old_key = doc.get("custom_bouw7_key")
    old_updated = doc.get("custom_bouw7_updated")
    doc.update(values)
    bind_doc(doc, row)
    changed = not existing or old_key != doc.custom_bouw7_key or old_updated != doc.custom_bouw7_updated or any(before[k] != doc.get(k) for k in values)
    if changed and not dry_run:
        if existing:
            doc.save(ignore_permissions=True)
        else:
            if doc.doctype == "Project" and doc.name:
                doc.insert(ignore_permissions=True, set_name=doc.name)
            else:
                doc.insert(ignore_permissions=True)
    if not dry_run:
        resolve_issue(kind, row)
    return "updated" if existing and changed else "unchanged" if existing else "created"

def source_party(row, dt):
    name_field = "customer_name" if dt == "Customer" else "supplier_name"
    name = text(row.get("name"))
    if not name:
        frappe.throw("Relatie heeft geen naam.")
    target = mapped(dt, row)
    if not target:
        matches = candidates(dt, {name_field: name})
        if len(matches) > 1:
            frappe.throw("Meerdere relaties met dezelfde naam; handmatige koppeling nodig.")
        target = matches[0].name if matches else None
    doc = frappe.get_doc(dt, target) if target else frappe.new_doc(dt)
    values = {name_field: name}
    if not target:
        values.update({"customer_type": "Company", "customer_group": config.customer_group, "territory": config.territory} if dt == "Customer" else {"supplier_type": "Company", "supplier_group": config.supplier_group})
    source_tax = text(row.get("vatNumber"))
    if source_tax and doc.get("tax_id") and text(doc.tax_id).replace(" ", "").upper() != source_tax.replace(" ", "").upper():
        frappe.throw("Btw-nummer wijkt af bij bestaande relatie; handmatige koppeling nodig.")
    fields = {"emailAddress": "zapp_email", "invoiceMail": "zapp_factuur_email", "phoneNumber": "zapp_telefoon", "mobilePhoneNumber": "zapp_mobiel", "cocNumber": "zapp_kvk", "iban": "zapp_iban", "vatNumber": "tax_id", "debtorNumber": "zapp_debiteurnummer"}
    for source, destination in fields.items():
        if row.get(source) is not None and doc.meta.has_field(destination):
            values[destination] = text(row.get(source))
    return save_doc(doc, row, values, bool(target))

def contact_sync(row):
    role = text((row.get("type") or {}).get("name"))
    if role == "own_organization":
        return "unchanged"
    destinations = ["Supplier"] if role in ["supplier", "subcontractor", "consultancy_firm"] else ["Customer"] if role in ["client", "customer"] else ["Customer", "Supplier"] if role in ["both", "client_and_supplier", "clientAndSupplier"] else []
    if not destinations:
        frappe.throw("Relatietype niet gekoppeld: " + role)
    results = [source_party(row, dt) for dt in destinations]
    return "created" if "created" in results else "updated" if "updated" in results else "unchanged"

def party_link(row, dt):
    if not row or not row.get("id"):
        return None
    target = mapped(dt, row)
    if target:
        return target
    field = "customer_name" if dt == "Customer" else "supplier_name"
    matches = candidates(dt, {field: text(row.get("name"))})
    if not matches and dry_run:
        return "PREVIEW-" + text(row["id"])
    if len(matches) != 1:
        frappe.throw("Relatie ontbreekt of is niet uniek: " + text(row.get("name")))
    doc = frappe.get_doc(dt, matches[0].name)
    if doc.get("custom_bouw7_key") and doc.custom_bouw7_key != source_key(row):
        frappe.throw("Relatienaam verwijst naar een andere Bouw7-relatie.")
    return doc.name

def employee_rate_values(row):
    if row.get("hourlyRate") is None or text(row.get("hourlyRate")) == "":
        return {}
    rate = frappe.utils.flt(row["hourlyRate"])
    if rate < 0:
        frappe.throw("Negatief bronuurtarief; handmatige controle nodig.")
    return {"custom_gross_hourly_rate": rate}

def employee_sync(row):
    target = mapped("Employee", row)
    name = (text(row.get("firstName")) + " " + text(row.get("lastName"))).strip()
    if not target:
        matches = candidates("Employee", {"employee_name": name})
        if len(matches) > 1:
            frappe.throw("Medewerkernaam is niet uniek.")
        target = matches[0].name if matches else None
    doc = frappe.get_doc("Employee", target) if target else frappe.new_doc("Employee")
    values = {"first_name": text(row.get("firstName")), "last_name": text(row.get("lastName"))}
    values.update(employee_rate_values(row))
    if not target:
        if not row.get("birthDate") or not row.get("dateOfEmployment"):
            frappe.throw("Nieuwe medewerker mist geboortedatum of datum indiensttreding.")
        values.update({"company": config.bedrijf1_company, "date_of_birth": day(row.get("birthDate")), "date_of_joining": day(row.get("dateOfEmployment")), "status": "Left" if row.get("dateOfResignation") else "Active"})
    for source, destination in {"birthDate": "date_of_birth", "dateOfEmployment": "date_of_joining", "dateOfResignation": "relieving_date", "phoneNumber": "cell_number"}.items():
        if row.get(source) is not None:
            values[destination] = day(row[source]) if destination in ["date_of_birth", "date_of_joining", "relieving_date"] else text(row[source])
    # Existing login addresses, roles and mailbox choices are managed in ERPNext.
    if row.get("dateOfResignation"):
        values["status"] = "Left"
    return save_doc(doc, row, values, bool(target))

def employee_user(row):
    if not row or not row.get("id"):
        return None
    employee = mapped("Employee", row)
    return frappe.db.get_value("Employee", employee, "user_id") if employee else None

def project_link(row, company):
    if not row:
        return None
    target = mapped("Project", row)
    if not target:
        number = text(row.get("fullProjectNumber") or row.get("number") or row.get("projectNumber"))
        matches = candidates("Project", {"name": number, "company": company}) if number else []
        target = matches[0].name if len(matches) == 1 else None
    if not target:
        if dry_run:
            return text(row.get("fullProjectNumber") or row.get("number") or row.get("projectNumber")) or "PREVIEW-" + text(row.get("id"))
        frappe.throw("Project is nog niet gekoppeld: " + text(row.get("name")))
    project = frappe.get_doc("Project", target)
    if project.company != company:
        frappe.throw("Project staat in een andere administratie.")
    return target

def project_sync(row):
    company = company_for(row)
    target = mapped("Project", row)
    number = text(row.get("fullProjectNumber") or row.get("projectNumber"))
    if not target:
        matches = candidates("Project", {"name": number}) if number else []
        if not matches:
            matches = candidates("Project", {"project_name": number + " - " + text(row.get("name"))})
        if not matches:
            matches = candidates("Project", {"project_name": text(row.get("name")), "company": company})
        if len(matches) > 1:
            frappe.throw("Projectherkenning is niet uniek.")
        target = matches[0].name if matches else None
    doc = frappe.get_doc("Project", target) if target else frappe.new_doc("Project")
    if target and doc.company != company:
        frappe.throw("Bestaand project staat in een andere administratie.")
    status = row.get("status") or {}
    values = {"company": company, "project_name": (number + " - " if number else "") + text(row.get("name")), "status": "Completed" if status.get("closesProject") else "Open", "custom_bouw7_status": text(status.get("name"))}
    if not target:
        if not number:
            frappe.throw("Projectnummer ontbreekt.")
        doc.name = number
    if row.get("contact"):
        values["customer"] = party_link(row["contact"], "Customer")
    fields = {"streetName": "zapp_straatnaam", "houseNumber": "zapp_huisnummer", "zipCode": "zapp_postcode", "city": "zapp_plaats", "reference": "zapp_referentie", "information": "zapp_omschrijving", "fixedPrice": "zapp_aanneemsom", "additionalWork": "zapp_meerwerk", "deliveryDate": "zapp_opleverdatum", "startDate": "expected_start_date", "endDate": "expected_end_date"}
    for source, destination in fields.items():
        if row.get(source) is not None:
            values[destination] = day(row[source]) if destination in ["zapp_opleverdatum", "expected_start_date", "expected_end_date"] else row[source]
    values["zapp_filiaal"] = text((row.get("branch") or {}).get("name"))
    values["zapp_categorie"] = text((row.get("category") or {}).get("name"))
    leader = row.get("projectLeader") or {}
    leader_user = employee_user(leader)
    if leader_user:
        values["zapp_projectleider"] = leader_user
    return save_doc(doc, row, values, bool(target))

def invoice_sync(row, purchase):
    dt = "Purchase Invoice" if purchase else "Sales Invoice"
    company = company_for(row)
    party_field = "supplier" if purchase else "customer"
    party = party_link(row.get("supplier") if purchase else row.get("contact"), "Supplier" if purchase else "Customer")
    if not party:
        frappe.throw("Factuurrelatie ontbreekt.")
    number = text(row.get("invoiceNumber"))
    if not number or not day(row.get("date")):
        frappe.throw("Factuurnummer of factuurdatum ontbreekt.")
    if any(row.get(k) is None for k in ["subTotal", "vatTotal", "total"]):
        frappe.throw("Factuurtotalen ontbreken in de bron.")
    if cents(row["subTotal"]) + cents(row["vatTotal"]) != cents(row["total"]):
        frappe.throw("Brontotalen sluiten niet aan.")
    target = mapped(dt, row)
    linked = bool(target)
    legacy = legacy_invoices.get("by_company", {}).get(company + "|" + text(row.get("entryNumber"))) if purchase else None
    if not target and legacy and legacy.get("company") == company and legacy.get("bill_no") == number and frappe.db.exists(dt, legacy.get("target")):
        target = legacy["target"]
    if not target:
        identity_filters = {"company": company, party_field: party, "bill_no" if purchase else "po_no": number, "posting_date": day(row["date"])}
        matches = candidates(dt, identity_filters)
        if not matches and not purchase:
            matches = candidates(dt, {"company": company, "name": number})
        if not matches and not purchase:
            legacy_lines = frappe.get_all("Sales Invoice Item", filters={"parenttype": "Sales Invoice", "description": ["like", "Bouw7 factuur " + number + " - %"]}, fields=["parent"], limit_page_length=20)
            parent_names = set([line.parent for line in legacy_lines])
            matches = []
            for parent in parent_names:
                old = frappe.get_doc("Sales Invoice", parent)
                if old.company == company and any(text(line.description).startswith("Bouw7 factuur " + number + " - ") for line in old.items):
                    matches.append(old)
        if len(matches) > 1:
            frappe.throw("Meerdere facturen met dezelfde identiteit.")
        target = matches[0].name if matches else None
        if not target and purchase:
            nearby = candidates(dt, {"company": company, "bill_no": number, "posting_date": day(row["date"])})
            if nearby:
                frappe.throw("Factuurnummer en datum bestaan al met een andere relatie. Geen dubbele factuur aangemaakt.")
            nearby = candidates(dt, {"supplier": party, "bill_no": number, "posting_date": day(row["date"])})
            if nearby:
                frappe.throw("Factuuridentiteit bestaat al in een andere administratie. Controleer de administratie.")
    doc = frappe.get_doc(dt, target) if target else frappe.new_doc(dt)
    if target and (doc.company != company or doc.get(party_field) != party):
        frappe.throw("Administratie of relatie wijkt af bij gekoppelde factuur.")
    totals_equal = target and cents(doc.net_total) == cents(row["subTotal"]) and cents(doc.grand_total) == cents(row["total"])
    if target and not linked and not totals_equal:
        return issue(kind, row, "Bestaande factuur gevonden, maar bedragen wijken af. Eerst identiteit en correctie controleren.", doc)
    if target and doc.docstatus != 0:
        if not totals_equal:
            return issue(kind, row, "Geboekte/geannuleerde factuur wijkt af. Correctie moet boekhoudkundig worden verwerkt.", doc)
        if day(doc.posting_date) != day(row["date"]) or day(doc.due_date) != (day(row.get("dueDate")) or day(row["date"])):
            return issue(kind, row, "Geboekte/geannuleerde factuur heeft afwijkende datums. Boekhoudkundige controle nodig.", doc)
        if not dry_run:
            bind_doc(doc, row)
            frappe.db.set_value(dt, doc.name, {"custom_bouw7_key": doc.custom_bouw7_key, "custom_bouw7_updated": doc.custom_bouw7_updated, "custom_bouw7_status": text(row.get("status"))}, update_modified=False)
        return "unchanged"
    status_number = frappe.utils.cint(row.get("status"))
    statuses = {0: "Nieuw", 1: "Accorderen", 2: "Open", 3: "Vervallen", 4: "Betaald", 5: "Afgewezen", 6: "Gepauzeerd"} if purchase else {0: "Open", 1: "Vervallen", 2: "Betaald", 3: "Concept"}
    values = {"company": company, party_field: party, "set_posting_time": 1, "posting_date": day(row["date"]), "due_date": day(row.get("dueDate")) or day(row["date"]), "custom_bouw7_status": statuses.get(status_number, text(status_number)), "zapp_exact": 1 if row.get("isBookedInExact") else 0, "custom_bouw7_invoice_number": number}
    if purchase:
        values.update({"bill_no": number, "bill_date": day(row["date"]), "zapp_inkoop_status": statuses.get(status_number, ""), "zapp_basecone": 1 if row.get("isOriginatingFromBasecone") else 0, "zapp_opmerking": text(row.get("comment")), "custom_bouw7_entry_number": text(row.get("entryNumber"))})
    else:
        values.update({"zapp_opmerkingen": text(row.get("note")), "zapp_werkadres": text(row.get("workAddress"))})
    if row.get("project"):
        values["project"] = project_link(row["project"], company)
    if not target or not totals_equal:
        if target and (len(doc.items) != 1 or doc.items[0].item_code != config.invoice_item):
            return issue(kind, row, "Bedrag gewijzigd bij factuur met eigen regels; handmatige controle nodig.", doc)
        company_doc = frappe.get_doc("Company", company)
        tax_account = config.bedrijf1_purchase_tax if purchase and company == config.bedrijf1_company else config.bedrijf2_purchase_tax if purchase else config.bedrijf1_sales_tax if company == config.bedrijf1_company else config.bedrijf2_sales_tax
        if cents(row["vatTotal"]) and not tax_account:
            frappe.throw("Btw-rekening ontbreekt voor administratie en factuurtype.")
        net = frappe.utils.flt(row["subTotal"])
        line = {"item_code": config.invoice_item, "description": "Bouw7 " + number + " — totaal volgens bronfactuur", "qty": -1 if net < 0 else 1, "rate": abs(net), "cost_center": company_doc.cost_center}
        line["expense_account" if purchase else "income_account"] = company_doc.default_expense_account if purchase else company_doc.default_income_account
        if values.get("project"):
            line["project"] = values["project"]
        values.update({"currency": "EUR", "conversion_rate": 1, "ignore_default_payment_terms_template": 1, "payment_terms_template": "", "is_return": 1 if net < 0 else 0, "update_stock": 0, "disable_rounded_total": 1, "items": [line], "taxes_and_charges": "", "taxes": [{"charge_type": "Actual", "account_head": tax_account, "description": "Btw volgens Bouw7-bronfactuur", "tax_amount": frappe.utils.flt(row["vatTotal"]), "cost_center": company_doc.cost_center}] if cents(row["vatTotal"]) else []})
        if purchase:
            values["credit_to"] = company_doc.default_payable_account
        else:
            values["debit_to"] = company_doc.default_receivable_account
    result = save_doc(doc, row, values, bool(target))
    if not dry_run and (day(doc.posting_date) != day(row["date"]) or day(doc.due_date) != (day(row.get("dueDate")) or day(row["date"]))):
        frappe.throw("ERPNext-datums wijken af van de bron; deze factuur wordt teruggedraaid.")
    if not dry_run and (cents(doc.net_total) != cents(row["subTotal"]) or cents(doc.grand_total) != cents(row["total"])):
        frappe.throw("ERPNext-berekening wijkt af van bron; deze factuur wordt teruggedraaid.")
    return result

def redact_request_logs(secrets, since):
    for entry in frappe.get_all("Error Log", filters={"creation": [">=", since]}, fields=["name", "error"], order_by="creation desc", limit_page_length=20):
        cleaned = entry.error or ""
        for secret in secrets:
            if secret:
                cleaned = cleaned.replace(secret, "[afgeschermd]")
        if cleaned != entry.error:
            frappe.db.set_value("Error Log", entry.name, "error", cleaned, update_modified=False)

def login():
    key = config.get_password("api_key")
    since = frappe.utils.now()
    try:
        response = frappe.make_post_request(SOURCE_URL + "/auth/login/z-next/apiKey", data={"apiKey": key}, headers={"Accept": "application/json"})
    except Exception:
        redact_request_logs([key], since)
        frappe.db.commit()
        return None
    if not response.get("token"):
        return None
    headers = {"Accept": "application/json", "Authorization": "Bearer " + response["token"]}
    try:
        organization = frappe.make_get_request(SOURCE_URL + "/organization", headers=headers)
        if organization.get("id") != frappe.utils.cint(config.organisatie_id):
            return None
    except Exception:
        redact_request_logs([key, response["token"]], since)
        frappe.db.commit()
        return None
    return headers

def source_retry_allowed(state, error):
    message = text(error).lower()
    temporary = any(marker in message for marker in ["502 server error", "503 server error", "504 server error", "read timed out", "connect timeout", "connection aborted", "connection reset"])
    return temporary and frappe.utils.cint(state.get("retry_count")) < 3

def validate_repair_ids(dataset, ids):
    if dataset not in KINDS or not isinstance(ids, list) or not ids or len(ids) > 200:
        frappe.throw("Kies een geldig onderdeel en 1 tot 200 controlepunten.")
    values = []
    for value in ids:
        if not text(value).isdigit() or frappe.utils.cint(value) < 1:
            frappe.throw("Ongeldige bron-ID.")
        number = frappe.utils.cint(value)
        target_type = {"contacts": "Customer", "employees": "Employee", "projects": "Project", "purchase_invoices": "Purchase Invoice", "sales_invoices": "Sales Invoice"}[dataset]
        known = frappe.db.exists(ISSUE_TYPE, {"dataset": dataset, "source_id": text(number), "resolved": 0})
        if not known:
            known = frappe.db.exists(target_type, {"custom_bouw7_key": text(config.organisatie_id) + ":" + text(number)})
        if not known:
            frappe.throw("Bron-ID heeft geen openstaande controle of bestaande bronkoppeling.")
        values.append(number)
    return sorted(list(set(values)))

def source_query(state, kind, batch_size):
    query = "id > " + text(state.get("last_id", 0))
    if state.get("repair_ids"):
        query = query + " AND id IN (" + ", ".join([text(i) for i in state["repair_ids"]]) + ")"
    elif state["watermarks"].get(kind) and not state["full"]:
        changed = 'updatedAt >= "' + state["watermarks"][kind] + '"'
        retry_ids = state.get("retry_ids", {}).get(kind) or []
        if retry_ids:
            changed = '(' + changed + ' OR id IN (' + ', '.join([text(i) for i in retry_ids]) + '))'
        query = query + ' AND ' + changed
    return query + " SORT(id, ASC) LIMIT " + text(batch_size)

def enqueue_worker(state):
    job_id = "zapp-bouw7-" + state["run"] + "-" + text(state["index"]) + "-" + text(state["offset"])
    if state.get("retry_count"):
        job_id = job_id + "-retry-" + text(state["retry_count"])
