                types = {"pdf": "application/pdf", "jpg": "image/jpeg", "jpeg": "image/jpeg", "png": "image/png", "webp": "image/webp", "ifc": "application/octet-stream"}
                frappe.response["type"] = "download"
                frappe.response["filename"] = meta.get("name")
                frappe.response["filecontent"] = remote.content
                frappe.response["content_type"] = types.get(extension, "application/octet-stream")
                frappe.response["display_content_as"] = "inline" if extension in ["pdf", "jpg", "jpeg", "png", "webp"] else "attachment"
else:
