# Server Script API: zapp_project_margins
def allocate_invoice(header, items):
    result = {}
    if not items:
        return {header.get("project") or "": frappe.utils.flt(header.get("base_net_total"))}
    for line in items:
        project = line.get("project") or header.get("project") or ""
        result[project] = result.get(project, 0) + frappe.utils.flt(line.get("base_net_amount"))
    # Keep reconciliation differences visible rather than assigning them arbitrarily.
    difference = frappe.utils.flt(header.get("base_net_total")) - sum(result.values())
    if abs(difference) > 0.02:
        result[""] = result.get("", 0) + difference
    return result

def labor_cost(line, gross_rate):
    hours = frappe.utils.flt(line.get("hours"))
    amount = frappe.utils.flt(line.get("base_costing_amount"))
    if amount:
        return (amount, 0, 0)
    if frappe.utils.flt(gross_rate) > 0:
        return (0, hours * frappe.utils.flt(gross_rate), 0)
    return (0, 0, hours)

def permitted_rows(dt, fields, filters):
    rows = frappe.get_list(dt, fields=fields, filters=filters, limit_page_length=50001, order_by="name asc")
    if len(rows) > 50000:
        frappe.throw("Te veel bronstukken. Kies een kortere periode.")
    return rows

def child_rows(dt, parenttype, parents, fields):
    result = []
    for start in range(0, len(parents), 200):
        rows = frappe.get_all(dt, filters={"parent": ["in", parents[start:start + 200]], "parenttype": parenttype}, fields=fields, limit_page_length=50001)
        if len(rows) > 50000:
            frappe.throw("Te veel regels in een bronbatch; overzicht afgebroken.")
        result.extend(rows)
    return result

def bucket(project, month):
    if month not in project["months"]:
        project["months"][month] = {"month": month, "revenue": 0, "purchase": 0, "labor": 0, "gross_estimate": 0, "missing_hours": 0, "hours": 0, "draft_revenue": 0, "draft_purchase": 0, "draft_labor": 0}
    return project["months"][month]

# Request boundary
user = frappe.session.user
if user == "Guest":
    frappe.throw("Aanmelden verplicht.", frappe.PermissionError)
roles = [r.role for r in frappe.get_doc("User", user).roles]
finance = user == "Administrator" or any(role in roles for role in ["System Manager", "Accounts Manager", "Accounts User"])
action = frappe.form_dict.get("action") or "read"
if action == "progress_info":
    doc = frappe.get_doc("Project", frappe.form_dict.get("project"))
    doc.check_permission("read")
    frappe.response["message"] = {"financial": doc.custom_financial_progress, "physical": doc.custom_physical_progress, "modified": doc.modified, "can_edit": doc.has_permission("write"), "updated": doc.custom_progress_updated}
elif action == "progress":
    if frappe.request.method != "POST":
        frappe.throw("Opslaan vereist POST.", frappe.PermissionError)
    if not frappe.form_dict.get("modified"):
        frappe.throw("De documentversie ontbreekt. Vernieuw eerst het project.")
    doc = frappe.get_doc("Project", frappe.form_dict.get("project"))
    doc.check_permission("write")
    for field in ["custom_financial_progress", "custom_physical_progress"]:
        value = frappe.form_dict.get(field)
        if value is None or value == "":
            frappe.throw("Vul beide percentages in.")
        if not str(value).strip().replace(".", "", 1).isdigit():
            frappe.throw("Gebruik een geldig percentage tussen 0 en 100.")
        number = frappe.utils.flt(value)
        if number < 0 or number > 100 or number != number:
            frappe.throw("Voortgang moet tussen 0 en 100 liggen.")
        doc.set(field, number)
    if str(doc.modified) != str(frappe.form_dict.get("modified")):
        frappe.throw("Het project is intussen gewijzigd. Vernieuw eerst.")
    doc.custom_progress_updated = frappe.utils.now()
    doc.custom_progress_by = user
    doc.save()
    frappe.response["message"] = {"saved": True, "modified": doc.modified}
else:
    if not finance:
        frappe.throw("Financiële rechten vereist.", frappe.PermissionError)
    year = frappe.utils.cint(frappe.form_dict.get("year"))
    if year and (year < 2000 or year > 2100):
        frappe.throw("Ongeldig jaar.")
    include_drafts = frappe.utils.cint(frappe.form_dict.get("include_drafts")) == 1
    company = frappe.form_dict.get("company") or ""
    projects = permitted_rows("Project", ["name", "project_name", "company", "status", "custom_financial_progress", "custom_physical_progress", "custom_progress_updated"], {})
    companies = sorted(list(set([p.company for p in projects if p.company])))
    projects = [p for p in projects if not company or p.company == company]
    relevant_companies = [company] if company else companies
    for name in relevant_companies:
        if name and frappe.db.get_value("Company", name, "default_currency") != "EUR":
            frappe.throw("Dit overzicht gebruikt EUR. Selecteer een administratie met EUR als basisvaluta.")
    project_map = {}
    for p in projects:
        project_map[p.name] = {"name": p.name, "project_name": p.project_name, "company": p.company, "status": p.status, "financial_progress": p.custom_financial_progress, "physical_progress": p.custom_physical_progress, "progress_updated": p.custom_progress_updated, "months": {}}
    warnings = []
    unassigned = {"revenue": 0, "purchase": 0, "hours": 0}
    source_counts = {}
    for dt, category in [["Sales Invoice", "revenue"], ["Purchase Invoice", "purchase"]]:
        filters = [["docstatus", "in", [0, 1] if include_drafts else [1]]]
        if company:
            filters.append(["company", "=", company])
        if year:
            filters.append(["posting_date", "between", [str(year) + "-01-01", str(year) + "-12-31"]])
        headers = permitted_rows(dt, ["name", "project", "company", "posting_date", "base_net_total", "docstatus"], filters)
        source_counts[dt] = len(headers)
        lines = child_rows(dt + " Item", dt, [h.name for h in headers], ["parent", "project", "base_net_amount"])
        by_parent = {}
        for line in lines:
            if line.parent not in by_parent:
                by_parent[line.parent] = []
            by_parent[line.parent].append(line)
        for header in headers:
            for project, amount in allocate_invoice(header, by_parent.get(header.name, [])).items():
                target = project_map.get(project)
                if target and target["company"] == header.company:
                    values = bucket(target, str(header.posting_date)[:7])
                    values[category] = values[category] + amount
                    if header.docstatus == 0:
                        values["draft_" + category] = values["draft_" + category] + amount
                else:
                    unassigned[category] = unassigned[category] + amount
    # Only parents readable to the caller are used before fetching their child rows.
    filters = [["docstatus", "in", [0, 1] if include_drafts else [1]]]
    if company:
        filters.append(["company", "=", company])
    sheets = permitted_rows("Timesheet", ["name", "employee", "company", "docstatus"], filters)
    sheet_map = {s.name: s for s in sheets}
    lines = child_rows("Timesheet Detail", "Timesheet", [s.name for s in sheets], ["parent", "project", "hours", "base_costing_amount", "from_time"])
    employees = list(set([s.employee for s in sheets if s.employee]))
    rates = {}
    for start in range(0, len(employees), 200):
        # Rates never leave this endpoint: only project aggregates are returned.
        for e in frappe.get_all("Employee", filters={"name": ["in", employees[start:start + 200]]}, fields=["name", "custom_gross_hourly_rate"], limit_page_length=200):
            rates[e.name] = e.custom_gross_hourly_rate
    for line in lines:
        date = str(line.from_time or "")
        if year and date[:4] != str(year):
            continue
        parent = sheet_map[line.parent]
        target = project_map.get(line.project)
        if not target or target["company"] != parent.company:
            unassigned["hours"] = unassigned["hours"] + frappe.utils.flt(line.hours)
            continue
        if len(date) < 7:
            warnings.append("Uren zonder datum zijn niet meegenomen.")
            continue
        values = bucket(target, date[:7])
        parts = labor_cost(line, rates.get(parent.employee))
        recorded = parts[0]
        estimated = parts[1]
        missing = parts[2]
        values["labor"] = values["labor"] + recorded
        values["gross_estimate"] = values["gross_estimate"] + estimated
        values["missing_hours"] = values["missing_hours"] + missing
        values["hours"] = values["hours"] + frappe.utils.flt(line.hours)
        if parent.docstatus == 0:
            values["draft_labor"] = values["draft_labor"] + recorded + estimated
    result = []
    for project in project_map.values():
        project["months"] = sorted(project["months"].values(), key=lambda x: x["month"])
        for field in ["revenue", "purchase", "labor", "gross_estimate", "missing_hours", "hours", "draft_revenue", "draft_purchase", "draft_labor"]:
            project[field] = sum([m[field] for m in project["months"]])
        project["cost"] = project["purchase"] + project["labor"] + project["gross_estimate"]
        project["margin"] = project["revenue"] - project["cost"]
        project["margin_percent"] = project["margin"] / project["revenue"] * 100 if project["revenue"] > 0 else None
        result.append(project)
    frappe.response["message"] = {"projects": result, "companies": companies, "unassigned": unassigned, "warnings": list(set(warnings)), "source_counts": source_counts, "include_drafts": include_drafts, "as_of": frappe.utils.now()}

