URL = "https://ddapi20-waterwebservices.rijkswaterstaat.nl/ONLINEWAARNEMINGENSERVICES/OphalenWaarnemingen"
STATIONS = [
    ["gouda.hollandscheijssel", "Gouda, Hollandsche IJssel"],
    ["krimpenaandeijssel.hollandscheijssel", "Krimpen a/d IJssel, Hollandsche IJssel"],
    ["schoonhoven", "Schoonhoven, Lek"],
    ["krimpenaandelek.lek", "Krimpen a/d Lek, Lek"],
    ["dordrecht.oudemaas.benedenmerwede", "Dordrecht, Oude Maas"],
    ["weesp.amsterdamrijnkanaal", "Weesp, Amsterdam-Rijnkanaal"],
    ["amsterdam.surinamekade", "Amsterdam, Surinamekade (IJ)"],
    ["amsterdam.schellingwouderbrug", "Amsterdam, Schellingwouderbrug"],
]
nu = frappe.utils.now_datetime()
begin = str(frappe.utils.add_to_date(nu, hours=-26))[:19].replace(" ", "T") + ".000+01:00"
eind = str(frappe.utils.add_to_date(nu, hours=25))[:19].replace(" ", "T") + ".000+01:00"
uit = []
for st in STATIONS:
    rij = {"code": st[0], "naam": st[1], "meting": [], "verwachting": [], "astronomisch": []}
    try:
        res = frappe.make_post_request(URL, data=json.dumps({
            "Locatie": {"Code": st[0]},
            "AquoPlusWaarnemingMetadata": {"AquoMetadata": {"Compartiment": {"Code": "OW"}, "Grootheid": {"Code": "WATHTE"}}},
            "Periode": {"Begindatumtijd": begin, "Einddatumtijd": eind}
        }), headers={"Content-Type": "application/json"})
        for w in (res or {}).get("WaarnemingenLijst") or []:
            soort = (w.get("AquoMetadata") or {}).get("ProcesType")
            if soort in rij:
                rij[soort] = [[m.get("Tijdstip"), (m.get("Meetwaarde") or {}).get("Waarde_Numeriek")] for m in w.get("MetingenLijst") or []]
    except Exception as e:
        rij["fout"] = "Geen gegevens: " + str(e)[:200]
